diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..77dbb56
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,47 @@
+import { isDate } from "../dates.js";
+import { AppError } from "../errors.js";
+import { memoryStore } from "../db/store.js";
+import { consume } from "../domain/batches.js";
+import { getDish } from "../domain/menu.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { parseCsv } from "./csv.js";
+
+/** Imports complete tickets atomically and returns ticket and dish counts. */
+export function importSales(store, text) {
+  const lines = text.split(/\r?\n/).map((line, i) => ({ line, row: i + 1 })).filter(({ line }) => line.trim());
+  const header = lines.shift();
+  if (!header || parseCsv(header.line)[0].join(",") !== "ticket,soldAt,dishId,qty")
+    throw new AppError("bad_request", { reason: "row 1: expected ticket,soldAt,dishId,qty" });
+  const draft = memoryStore(store.data);
+  const previous = new Set(draft.data.sales.map((s) => s.ticket));
+  const tickets = new Set();
+  let dishes = 0;
+  for (const { line, row } of lines) {
+    const fail = (reason) => { throw new AppError("bad_request", { reason: `row ${row}: ${reason}` }); };
+    if (!/^(?:[^",]*|"(?:[^"]|"")*")(?:,(?:[^",]*|"(?:[^"]|"")*")){3}$/.test(line)) fail("invalid CSV row");
+    const [ticket, soldAt, dishText, qtyText] = parseCsv(line)[0].map((v) => v.trim());
+    if (!ticket) fail("ticket is required");
+    if (!/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?(?:Z|[+-]\d\d:\d\d)$/.test(soldAt) || !isDate(soldAt.slice(0, 10)) || !Number.isFinite(Date.parse(soldAt))) fail("invalid soldAt");
+    if (!/^[1-9]\d*$/.test(dishText) || !Number.isSafeInteger(Number(dishText))) fail("invalid dishId");
+    if (!/^[1-9]\d*$/.test(qtyText) || !Number.isSafeInteger(Number(qtyText))) fail("invalid qty");
+    let dish, recipe;
+    try { dish = getDish(draft, Number(dishText)); recipe = getRecipe(draft, dish.recipeId); } catch (error) {
+      if (!(error instanceof AppError)) throw error;
+      fail("unknown dish or recipe");
+    }
+    if (previous.has(ticket)) continue;
+    const ingredients = scaled(recipe, Number(qtyText)).filter((n) => n.qty > 0);
+    try {
+      for (const n of ingredients) consume(draft, n.itemId, n.qty, { at: new Date(soldAt).toISOString(), ref: `sale:${ticket}` });
+    } catch (error) {
+      if (!(error instanceof AppError)) throw error;
+      if (error.code === "not_enough_stock") fail(`not enough stock for ${error.params.item}`);
+      fail("invalid ingredient");
+    }
+    draft.data.sales.push({ ticket, soldAt: new Date(soldAt).toISOString(), dishId: dish.id, qty: Number(qtyText), ingredients });
+    tickets.add(ticket);
+    dishes += Number(qtyText);
+  }
+  store.data = draft.data;
+  return { tickets: tickets.size, dishes };
+}
